-- Create schema as SYSTEM:
CREATE USER skillswap IDENTIFIED BY skillswap;
GRANT CONNECT, RESOURCE TO skillswap;
ALTER USER skillswap QUOTA UNLIMITED ON USERS;

-- Then connect as SKILLSWAP and run:
CREATE TABLE swap_users(id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR2(100) NOT NULL,email VARCHAR2(150) UNIQUE NOT NULL,password VARCHAR2(100) NOT NULL,bio VARCHAR2(500));
CREATE TABLE skills(id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR2(100) UNIQUE NOT NULL);
CREATE SEQUENCE user_skill_seq START WITH 1 INCREMENT BY 1;
CREATE TABLE user_skills(id NUMBER PRIMARY KEY,user_id NUMBER REFERENCES swap_users(id),skill_id NUMBER REFERENCES skills(id),skill_type VARCHAR2(10) CHECK(skill_type IN('TEACH','LEARN')));
CREATE SEQUENCE exchange_seq START WITH 1 INCREMENT BY 1;
CREATE TABLE exchange_requests(id NUMBER PRIMARY KEY,sender_id NUMBER REFERENCES swap_users(id),receiver_id NUMBER REFERENCES swap_users(id),skill_id NUMBER REFERENCES skills(id),status VARCHAR2(10) DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT SYSTIMESTAMP);

